import { USDC_ABSTRACT_MAINNET, USDC_ABSTRACT_TESTNET, getToken, nativeOnChain } from 'uniswap/src/constants/tokens'
import { RPCType, UniverseChainId, isUniverseChainId } from 'uniswap/src/features/chains/types'
import { getChainInfo } from 'uniswap/src/features/chains/chainInfo'
