const USDC_DEFAULT_MIN = 1_000e6
const USDC_18_DEFAULT_MIN = 1_000e18

// Stablecoin amounts used when calculating spot price for a given currency.
// Kept for compatibility with callers that use this constant.
export const STABLECOIN_AMOUNT_OUT: Record<UniverseChainId, CurrencyAmount<Token>> = {
  [UniverseChainId.Mainnet]: CurrencyAmount.fromRawAmount(USDC_ABSTRACT_MAINNET, USDC_DEFAULT_MIN),
  [UniverseChainId.Sepolia]: CurrencyAmount.fromRawAmount(USDC_ABSTRACT_TESTNET, USDC_18_DEFAULT_MIN),
}

// Hardcoded USD prices for testnet tokens
const TESTNET_PRICES: Record<string, string> = {
  '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d': '3500', // WETH testnet
  '0xb6313be1c20dc222199ec567951abc6b5b64dfd6': '0.20', // ABX testnet
}

interface DexScreenerToken {
  address: string
  name: string
  symbol: string
}

interface DexScreenerPair {
  chainId: string
  dexId: string
  url: string
  pairAddress: string
  baseToken: DexScreenerToken
  quoteToken: DexScreenerToken
  priceUsd?: string
  liquidity?: {
    usd?: number
  }
}

// DexScreener tokens endpoint returns array directly
type DexScreenerResponse = DexScreenerPair[]

const V3_TICK_SPACINGS = [1, 50, 100, 200, 2000]

export function normalizeCurrencyForUsdPricing(currency?: Currency): Currency | undefined {
  if (!currency || !isUniverseChainId(currency.chainId)) {
    return currency
  }

  if (currency.isToken) {
    const nativeCurrency = nativeOnChain(currency.chainId)
    const wrapped = wrappedNativeCurrency(currency.chainId)
    const hasEquals = typeof (currency as any)?.equals === 'function'
    const matchesWrapped = hasEquals
      ? (currency as Currency).equals(wrapped)
      : typeof (currency as any)?.address === 'string' &&
        (currency as any).address.toLowerCase() === wrapped.address.toLowerCase()

    if (matchesWrapped) {
      return nativeCurrency
    }
  }

  return currency
}

async function fetchPoolPriceFromAbstractDex(
  chainId: UniverseChainId,
  baseCurrency: Currency,
  usdcToken: Token,
): Promise<Price<Currency, Currency> | null> {
  if (!isAbstractChain(chainId)) {
    return null
  }

  const { clFactory } = getAbstractContracts(chainId)
  if (!clFactory) {
    return null
  }

  const rpcUrl = getChainInfo(chainId).rpcUrls[RPCType.Default]?.http?.[0]
  if (!rpcUrl) {
    return null
  }

  const provider = new ethers.providers.JsonRpcProvider(rpcUrl)
  const poolDetectionService = new PoolDetectionService()

  const baseToken = baseCurrency.isToken ? (baseCurrency as Token) : baseCurrency.wrapped
  const quoteToken = usdcToken

  const baseSortsBefore = baseToken.sortsBefore(quoteToken)
  const token0 = baseSortsBefore ? baseToken : quoteToken
  const token1 = baseSortsBefore ? quoteToken : baseToken

  for (const tickSpacing of V3_TICK_SPACINGS) {
    try {
      const poolInfo = await poolDetectionService.getPoolInfo(
        token0.address,
        token1.address,
        tickSpacing,
        clFactory,
        provider,
      )

      if (!poolInfo.exists || poolInfo.sqrtPriceX96 === '0') {
        continue
      }

      const priceForToken0 = tickToPrice(token0, token1, poolInfo.tick)
      const priceForToken1 = tickToPrice(token1, token0, poolInfo.tick)
      const priceForBase = baseSortsBefore ? priceForToken0 : priceForToken1

      return new Price(baseCurrency, usdcToken, priceForBase.denominator, priceForBase.numerator)
    } catch (error) {
      // try next tick spacing
      continue
    }
  }

  return null
}

function mapPriceToRequestedCurrency(
  price: Price<Currency, Currency> | null | undefined,
  requestedCurrency?: Currency,
  normalizedCurrency?: Currency,
): Price<Currency, Currency> | undefined {
  if (!price) {
    return undefined
  }

  if (!requestedCurrency || !normalizedCurrency) {
    return price ?? undefined
  }

  const requestedHasEquals = typeof (requestedCurrency as any)?.equals === 'function'
  if (
    requestedCurrency.isNative &&
    normalizedCurrency.isNative &&
    requestedCurrency.chainId === normalizedCurrency.chainId
  ) {
    return price
  }

  if (requestedHasEquals && (requestedCurrency as Currency).equals(normalizedCurrency)) {
    return price
  }

  if (normalizedCurrency.isNative && isUniverseChainId(normalizedCurrency.chainId)) {
    const wrapped = wrappedNativeCurrency(normalizedCurrency.chainId)
    const matchesWrapped = requestedHasEquals
      ? (requestedCurrency as Currency).equals(wrapped)
      : requestedCurrency.isToken &&
        typeof (requestedCurrency as any)?.address === 'string' &&
        (requestedCurrency as any).address.toLowerCase() === wrapped.address.toLowerCase()

    if (matchesWrapped) {
      return new Price(wrapped, price.quoteCurrency, price.denominator, price.numerator)
    }
  }

  return price
}

/**
 * Returns the price in USDC of the input currency
 * @param currency currency to compute the USDC price of
 */
export function useUSDCPrice(
  currency?: Currency,
  pollInterval: PollingInterval = PollingInterval.Fast,
): {
  price: Price<Currency, Currency> | undefined
  isLoading: boolean
} {
  const normalizedCurrency = useMemo(() => normalizeCurrencyForUsdPricing(currency), [currency])
  const chainId = normalizedCurrency?.chainId
  const { isTestnetModeEnabled } = useEnabledChains()

  // Only allow fetching on the chain that matches the current mode.
  // - Testnet mode: Sepolia only
  // - Mainnet mode: Abstract Mainnet only
  const chainMatchesMode = useMemo(() => {
    if (!isUniverseChainId(chainId)) return false
    return isTestnetModeEnabled ? chainId === UniverseChainId.Sepolia : chainId === UniverseChainId.Mainnet
  }, [chainId, isTestnetModeEnabled])

  const usdcToken = chainMatchesMode && isUniverseChainId(chainId) ? getToken(chainId).usdc : undefined

  // avoid fetching price for stablecoin itself
  const currencyIsStablecoin = Boolean(
    usdcToken && normalizedCurrency && areCurrencyIdsEqual(currencyId(normalizedCurrency), currencyId(usdcToken)),
  )

  // Price fetch: DexScreener for mainnet, hardcoded for testnet
  const { data, isLoading } = useQuery({
    queryKey: ['token-usd-price', chainId, normalizedCurrency?.wrapped.address],
    enabled: Boolean(
      normalizedCurrency &&
      usdcToken &&
      !currencyIsStablecoin &&
      isUniverseChainId(chainId) &&
      chainMatchesMode,
    ),
    refetchInterval: 60000, // Refetch every 60 seconds
    staleTime: 60000, // Cache for 60 seconds
    refetchOnWindowFocus: false,
    queryFn: async (): Promise<Price<Currency, Currency> | null> => {
      if (!normalizedCurrency || !usdcToken || !isUniverseChainId(chainId) || !chainMatchesMode) {
        return null
      }

      const tokenAddr = normalizedCurrency.isNative ? normalizedCurrency.wrapped.address : normalizedCurrency.address
      if (!tokenAddr || tokenAddr.toLowerCase() === '0x0000000000000000000000000000000000000000') {
        return null
      }

      // For testnet, use hardcoded prices
      if (chainId === UniverseChainId.Sepolia) {
        const hardcodedPrice = TESTNET_PRICES[tokenAddr.toLowerCase()]
        if (hardcodedPrice) {
          // Create a Price object: 1 token = X USDC
          // Price(baseCurrency, quoteCurrency, denominator, numerator)
          // denominator = 10^tokenDecimals (represents 1 whole token)
          // numerator = priceUsd * 10^usdcDecimals (represents price in USDC)
          const tokenDecimals = normalizedCurrency.decimals
          const usdcDecimals = usdcToken.decimals
          const denominator = Math.pow(10, tokenDecimals).toString()
          const numerator = (parseFloat(hardcodedPrice) * Math.pow(10, usdcDecimals)).toFixed(0)
          return new Price(normalizedCurrency, usdcToken, denominator, numerator)
        }
        return null
      }

      // For mainnet, use DexScreener API
      try {
        const response = await fetch(
          `https://api.dexscreener.com/tokens/v1/abstract/${tokenAddr}`,
          { headers: { 'Accept': 'application/json' } }
        )

        if (!response.ok) {
          throw new Error(`DexScreener request failed with status ${response.status}`)
        }

        const pairs: DexScreenerResponse = await response.json()

        if (!pairs || pairs.length === 0) {
          throw new Error('DexScreener returned no results')
        }

        // Find the pair with highest liquidity that has a USD price
        const bestPair = pairs
          .filter(p => p.priceUsd && p.liquidity?.usd)
          .sort((a, b) => (b.liquidity?.usd || 0) - (a.liquidity?.usd || 0))[0]

        if (!bestPair || !bestPair.priceUsd) {
          throw new Error('DexScreener returned no price data')
        }

        // Create Price object: 1 token = X USDC
        // denominator = 10^tokenDecimals (represents 1 whole token)
        // numerator = priceUsd * 10^usdcDecimals (represents price in USDC)
        const tokenDecimals = normalizedCurrency.decimals
        const usdcDecimals = usdcToken.decimals
        const denominator = Math.pow(10, tokenDecimals).toString()
        const numerator = (parseFloat(bestPair.priceUsd) * Math.pow(10, usdcDecimals)).toFixed(0)
        return new Price(normalizedCurrency, usdcToken, denominator, numerator)
      } catch (error) {
        const fallbackPrice =
          isUniverseChainId(chainId) && usdcToken
            ? await fetchPoolPriceFromAbstractDex(chainId, normalizedCurrency, usdcToken)
            : null
        return fallbackPrice
      }
    },
  })

  return useMemo(() => {
    const mappedPrice = mapPriceToRequestedCurrency(data ?? undefined, currency, normalizedCurrency)

    if (!usdcToken || !chainMatchesMode) {
      return { price: undefined, isLoading: false }
    }

    if (currencyIsStablecoin) {
      return { price: new Price(usdcToken, usdcToken, '1', '1'), isLoading: false }
    }

    return { price: mappedPrice, isLoading }
  }, [currency, currencyIsStablecoin, data, isLoading, normalizedCurrency, usdcToken])
}

export function useUSDCValue(
  currencyAmount: CurrencyAmount<Currency> | undefined | null,
): CurrencyAmount<Currency> | null {
  const { price } = useUSDCPrice(currencyAmount?.currency)

  return useMemo(() => {
    if (!price || !currencyAmount) {
      return null
    }
    try {
      return price.quote(currencyAmount)
    } catch (error) {
      return null
    }
  }, [currencyAmount, price])
}

/**
 * @param currencyAmount
 * @returns Returns fiat value of the currency amount, and loading status of the currency<->stable quote
 */
export function useUSDCValueWithStatus(currencyAmount: CurrencyAmount<Currency> | undefined | null): {
  value: CurrencyAmount<Currency> | null
  isLoading: boolean
} {
  const { price, isLoading } = useUSDCPrice(currencyAmount?.currency)

  return useMemo(() => {
    if (!price || !currencyAmount) {
      return { value: null, isLoading }
    }
    try {
      return { value: price.quote(currencyAmount), isLoading }
    } catch (error) {
      return {
        value: null,
        isLoading: false,
      }
    }
  }, [currencyAmount, isLoading, price])
}
