export type SortedPortfolioBalances = {
  balances: PortfolioBalance[]
  hiddenBalances: PortfolioBalance[]
}

export type PortfolioTotalValue = {
  balanceUSD: number | undefined
  percentChange: number | undefined
  absoluteChangeUSD: number | undefined
}

export type PortfolioCacheUpdater = (hidden: boolean, portfolioBalance?: PortfolioBalance) => void

/**
 * Returns all balances indexed by checksummed currencyId for a given address
 * @param address
 * @param queryOptions.pollInterval optional `PollingInterval` representing polling frequency.
 *  If undefined, will query once and not poll.
 * NOTE:
 *  on TokenDetails, useBalances relies rely on usePortfolioBalances but don't need polling versions of it.
 *  Including polling was causing multiple polling intervals to be kicked off with usePortfolioBalances.
 *  Same with on Token Selector's TokenSearchResultList, since the home screen has a usePortfolioBalances polling hook,
 *  we don't need to duplicate the polling interval when token selector is open
 * @param queryOptions - QueryHookOptions type for usePortfolioBalancesQuery to be set if not already set internally.
 */
export function usePortfolioBalances({
  address,
  ...queryOptions
}: {
  address?: Address
} & any): GqlResult<Record<CurrencyId, PortfolioBalance>> & { networkStatus: NetworkStatus } {
  const account = useAccountMeta()
  const { chains } = useEnabledChains()
  
  // Get user-imported tokens from Redux state
  const userAddedTokens = useSelector((state: any) => state.user?.tokens || {})
  
  // Get provider for the primary chain (we'll focus on one chain for now)
  const primaryChain = chains.find(isAbstractChain) || UniverseChainId.Mainnet
  const provider = useEthersProvider({ chainId: primaryChain })

  const { data: balancesData, isLoading: loading, error, refetch } = useQuery({
    queryKey: ['portfolio-balances', address, chains, userAddedTokens],
    queryFn: async () => {
      if (!address || !provider) return {}

      const allBalances: Record<CurrencyId, PortfolioBalance> = {}

      try {
        // Get native ETH balance
        const ethBalance = await provider.getBalance(address)
        if (ethBalance.gt(0)) {
          const nativeCurrency = NativeCurrency.onChain(primaryChain)
          const ethCurrencyId = currencyId(nativeCurrency)
          
          const safetyInfo = getCurrencySafetyInfo(SafetyLevel.Verified, {
            attackTypes: [],
            result: ProtectionResult.Benign,
          })

          // Convert raw balance to human readable format (divide by 10^18 for ETH)
          const formattedEthBalance = formatUnits(ethBalance, nativeCurrency.decimals)
          const parsedEthBalance = Number.parseFloat(formattedEthBalance)
          
          allBalances[ethCurrencyId] = {
            id: `eth-balance-${primaryChain}`,
            cacheId: `TokenBalance:eth-balance-${primaryChain}`,
            quantity: Number.isFinite(parsedEthBalance) ? parsedEthBalance : 0,
            quantityRaw: ethBalance.toString(),
            balanceUSD: undefined, // We don't have price data for now
            currencyInfo: {
              currencyId: ethCurrencyId,
              currency: nativeCurrency,
              logoUrl: '/images/tokens/eth-logo.png', // ETH logo for native currency
              safetyLevel: SafetyLevel.Verified,
              safetyInfo,
              isSpam: false,
            },
            relativeChange24: undefined,
            isHidden: false,
          }
        }

        // Get all tokens to check - both known Abstract tokens and user-imported tokens
        const abstractTokens = getAbstractTokenList(primaryChain)
        const userTokensForChain = userAddedTokens[primaryChain] || {}
        
        // Convert user-imported serialized tokens to Token instances
        const userTokens: Token[] = Object.values(userTokensForChain).map((serializedToken: any) => 
          new Token(
            serializedToken.chainId,
            serializedToken.address,
            serializedToken.decimals,
            serializedToken.symbol,
            serializedToken.name
          )
        )

        // Combine both token lists, avoiding duplicates
        const allTokens = [...abstractTokens]
        for (const userToken of userTokens) {
          const isDuplicate = abstractTokens.some(token => 
            token.address.toLowerCase() === userToken.address.toLowerCase()
          )
          if (!isDuplicate) {
            allTokens.push(userToken)
          }
        }
        
        // For now, make individual calls (we can optimize with multicall later)
        for (const token of allTokens) {
          try {
            const tokenContract = getContract(token.address, ERC20_ABI, provider)
            if (!tokenContract) continue

            const balance: BigNumber = await tokenContract.balanceOf(address)
            
            if (balance.gt(0)) {
              const tokenCurrencyId = currencyId(token)
              
              const safetyInfo = getCurrencySafetyInfo(SafetyLevel.Verified, {
                attackTypes: [],
                result: ProtectionResult.Benign,
              })

              // Convert raw balance to human readable format using token decimals
              const formattedTokenBalance = formatUnits(balance, token.decimals)
              const parsedTokenBalance = Number.parseFloat(formattedTokenBalance)
              
              allBalances[tokenCurrencyId] = {
                id: `token-balance-${token.address}-${primaryChain}`,
                cacheId: `TokenBalance:token-balance-${token.address}-${primaryChain}`,
                quantity: Number.isFinite(parsedTokenBalance) ? parsedTokenBalance : 0,
                quantityRaw: balance.toString(),
                balanceUSD: undefined, // We don't have price data for now
                currencyInfo: {
                  currencyId: tokenCurrencyId,
                  currency: token,
                  logoUrl: getTokenLogoUrl(token.address),
                  safetyLevel: SafetyLevel.Verified,
                  safetyInfo,
                  isSpam: false,
                },
                relativeChange24: undefined,
                isHidden: false,
              }
            }
          } catch (error) {
            console.warn(`Failed to fetch balance for token ${token.symbol}:`, error)
          }
        }
      } catch (error) {
        console.warn(`Failed to fetch balances for chain ${primaryChain}:`, error)
      }

      return allBalances
    },
    enabled: !!address && !queryOptions?.skip,
    refetchInterval: 30000, // Refresh every 30 seconds
  })

  const retry = useCallback(() => {
    return refetch()
  }, [refetch])

  return {
    data: balancesData,
    loading,
    networkStatus: loading ? NetworkStatus.loading : NetworkStatus.ready,
    refetch: retry,
    error,
  }
}

// Simplified implementation for Abstract chains - we don't need complex caching for now

export function usePortfolioTotalValue({
  address,
}: {
  address?: Address
  pollInterval?: any
  onCompleted?: () => void
  fetchPolicy?: any
}): GqlResult<PortfolioTotalValue> & { networkStatus: NetworkStatus } {
  // Simplified implementation - just return zeros for now
  return {
    data: {
      balanceUSD: 0,
      percentChange: 0,
      absoluteChangeUSD: 0,
    },
    loading: false,
    networkStatus: NetworkStatus.ready,
    refetch: () => Promise.resolve({ data: { balanceUSD: 0, percentChange: 0, absoluteChangeUSD: 0 } }),
    error: undefined,
  }
}

// Simplified stubs for remaining functions that are used by the UI

export function useTokenBalancesGroupedByVisibility({
  balancesById,
}: {
  balancesById?: Record<string, PortfolioBalance>
}): {
  shownTokens: PortfolioBalance[] | undefined
  hiddenTokens: PortfolioBalance[] | undefined
} {
  return useMemo(() => {
    if (!balancesById) {
      return { shownTokens: undefined, hiddenTokens: undefined }
    }

    const balances = Object.values(balancesById)
    return {
      shownTokens: balances.length ? balances : undefined,
      hiddenTokens: undefined, // No hidden tokens for now
    }
  }, [balancesById])
}

export function useSortedPortfolioBalances({
  address,
}: {
  address?: Address
  pollInterval?: any
  onCompleted?: () => void
}): GqlResult<SortedPortfolioBalances> & { networkStatus: NetworkStatus } {
  const {
    data: balancesById,
    loading,
    networkStatus,
    refetch,
  } = usePortfolioBalances({ address })

  const { shownTokens } = useTokenBalancesGroupedByVisibility({ balancesById })

  return {
    data: {
      balances: shownTokens || [],
      hiddenBalances: [],
    },
    loading,
    networkStatus,
    refetch,
    error: undefined,
  }
}

export function useHighestBalanceNativeCurrencyId(address: Address, chainId?: UniverseChainId): CurrencyId {
  const { defaultChainId } = useEnabledChains()
  const targetChainId = chainId ?? defaultChainId
  const nativeCurrency = new NativeCurrency(targetChainId, 18, 'ETH', 'Ethereum')
  return currencyId(nativeCurrency)
}

