export type AbstractSubgraphType = 'v2' | 'v3' | 'gauges' | 'veabx' | 'positions' | 'votes'

export interface AbstractSubgraphEndpoint {
  url: string
  headers?: Record<string, string>
  label?: string
}

type ChainSubgraphEndpoints = Record<AbstractSubgraphType, AbstractSubgraphEndpoint[]>
type SubgraphProviderConfig = Record<UniverseChainId, ChainSubgraphEndpoints>

const SATSUMA_ORIGIN = 'https://subgraph.satsuma-prod.com'
const THE_GRAPH_GATEWAY_BASE = 'https://gateway.thegraph.com/api/subgraphs/id'

function createSatsumaEndpoint(
  apiPath: string,
  playgroundPath: string,
  label?: string
): AbstractSubgraphEndpoint {
  const normalizedPlayground = playgroundPath.startsWith('/')
    ? playgroundPath.slice(1)
    : playgroundPath

  return {
    url: `${SATSUMA_ORIGIN}/${apiPath}`,
    headers: {
      Origin: SATSUMA_ORIGIN,
      Referer: `${SATSUMA_ORIGIN}/${normalizedPlayground}`,
    },
    label,
  }
}

const HARD_CODED_GRAPH_TOKEN = '37482efe4d8f65836ae98a7f0d5af52c'

const GRAPH_AUTH_TOKEN =
  process.env.REACT_APP_THEGRAPH_API_TOKEN ??
  process.env.THEGRAPH_API_TOKEN ??
  HARD_CODED_GRAPH_TOKEN

function createTheGraphEndpoint(options: {
  subgraphId: string
  label: string
  referer?: string
  requiresAuth?: boolean
}): AbstractSubgraphEndpoint {
  const headers: Record<string, string> = {}
  const { requiresAuth = true, referer } = options

  if (requiresAuth && GRAPH_AUTH_TOKEN) {
    headers.Authorization = `Bearer ${GRAPH_AUTH_TOKEN}`
  }

  if (referer) {
    headers.Referer = referer
  }

  return {
    url: `${THE_GRAPH_GATEWAY_BASE}/${options.subgraphId}`,
    headers: Object.keys(headers).length > 0 ? headers : undefined,
    label: options.label,
  }
}

