const SUBGRAPH_PROVIDERS = {
  satsuma: {
    [UniverseChainId.Sepolia]: SATSUMA_SEPOLIA_ENDPOINTS,
    [UniverseChainId.Mainnet]: SATSUMA_MAINNET_ENDPOINTS,
  },
  legacy: {
    [UniverseChainId.Sepolia]: SATSUMA_SEPOLIA_ENDPOINTS,
    [UniverseChainId.Mainnet]: LEGACY_MAINNET_ENDPOINTS,
  },
  thegraph: {
    [UniverseChainId.Sepolia]: SATSUMA_SEPOLIA_ENDPOINTS,
    [UniverseChainId.Mainnet]: THE_GRAPH_MAINNET_ENDPOINTS,
  },
} satisfies Record<string, SubgraphProviderConfig>

type SubgraphProviderKey = keyof typeof SUBGRAPH_PROVIDERS

const requestedProvider = process.env.REACT_APP_ABSTRACT_SUBGRAPH_PROVIDER?.toLowerCase() as
  | SubgraphProviderKey
  | undefined

const defaultProviderKey: SubgraphProviderKey = GRAPH_AUTH_TOKEN ? 'thegraph' : 'satsuma'

const activeProviderKey: SubgraphProviderKey =
  (requestedProvider && requestedProvider in SUBGRAPH_PROVIDERS
    ? requestedProvider
    : defaultProviderKey)

const ACTIVE_SUBGRAPH_CONFIG = SUBGRAPH_PROVIDERS[activeProviderKey]

function createEndpointAccessor(config: ChainSubgraphEndpoints) {
  const pick = (type: AbstractSubgraphType): AbstractSubgraphEndpoint => {
    const endpoints = config[type]

    if (!endpoints || endpoints.length === 0) {
      throw new Error(`[abstractContracts] No subgraph endpoint configured for "${type}"`)
    }

    return endpoints[Math.floor(Math.random() * endpoints.length)]
  }

  return {
    get v2() {
      return pick('v2')
    },
    get v3() {
      return pick('v3')
    },
    get gauges() {
      return pick('gauges')
    },
    get veabx() {
      return pick('veabx')
    },
    get positions() {
      return pick('positions')
    },
    get votes() {
      return pick('votes')
    },
  }
}

export const ABSTRACT_SUBGRAPHS = {
  [UniverseChainId.Sepolia]: createEndpointAccessor(ACTIVE_SUBGRAPH_CONFIG[UniverseChainId.Sepolia]),
  [UniverseChainId.Mainnet]: createEndpointAccessor(ACTIVE_SUBGRAPH_CONFIG[UniverseChainId.Mainnet]),
}

